                    let mut d: size_t = 0 as size_t;
                    let mut offset: size_t = 0;
                    let mut limit: size_t = 0;
                    let mut source: *const uint8_t = ::core::ptr::null::<uint8_t>();
                    offset = dictionary_start
                        .wrapping_add(1 as size_t)
                        .wrapping_add((*addon).total_size)
